package com.careflow.appointment.model; import jakarta.persistence.*; @Entity @Table(name="doctors") public class Doctor{@Id @Column(name="user_id") private Long id; private String name; private String email; private String phone; private String specialization; private Integer experience; private String qualification; private Boolean available=true; public Long getId(){return id;}public String getName(){return name;}public String getEmail(){return email;}public String getPhone(){return phone;}public String getSpecialization(){return specialization;}public Integer getExperience(){return experience;}public String getQualification(){return qualification;}public Boolean getAvailable(){return available;}public void setId(Long v){id=v;}public void setName(String v){name=v;}public void setEmail(String v){email=v;}public void setPhone(String v){phone=v;}public void setSpecialization(String v){specialization=v;}public void setExperience(Integer v){experience=v;}public void setQualification(String v){qualification=v;}public void setAvailable(Boolean v){available=v;}}
